#include "companion_http.h"
#include <QCoreApplication>
#include <QFile>
#include <QSslKey>
#include <QSslSocket>
#include <QTcpServer>
#include <QTimer>
#include <QElapsedTimer>
#include <iostream>
#include <stdexcept>
using namespace companion;
void check(bool b){if(!b)throw std::runtime_error("HTTP test failure");}
template<class F>void rejects(F f){bool failed=false;try{f();}catch(const std::runtime_error&){failed=true;}check(failed);}
class Server:public QTcpServer {QSslCertificate certificate_;QSslKey key_;public:int requests{};Server(QSslCertificate c,QSslKey k):certificate_(c),key_(k){};void incomingConnection(qintptr descriptor)override{auto* socket=new QSslSocket(this);socket->setLocalCertificate(certificate_);socket->setPrivateKey(key_);socket->setPeerVerifyMode(QSslSocket::VerifyNone);check(socket->setSocketDescriptor(descriptor));connect(socket,&QSslSocket::disconnected,socket,&QObject::deleteLater);connect(socket,&QSslSocket::readyRead,socket,[this,socket]{auto bytes=socket->readAll();if(!bytes.startsWith("GET ")&&!bytes.startsWith("POST "))return;++requests;auto path=bytes.split(' ').value(1);if(path=="/v1/throttle"||path=="/v1/stall-body"){
 const qint64 total=path=="/v1/throttle"?2300000:100;socket->write("HTTP/1.1 200 OK\r\nContent-Length: "+QByteArray::number(total)+"\r\nConnection: close\r\n\r\n");
 auto* tick=new QTimer(socket);tick->setInterval(100);connect(tick,&QTimer::timeout,socket,[socket,tick,total,sent=qint64(0)]()mutable{const auto n=std::min<qint64>(3000,total-sent);socket->write(QByteArray(n,'p'));sent+=n;if(sent==total){tick->stop();socket->disconnectFromHost();}else if(total==100)tick->stop();});
 if(total==100){socket->write("p");}else tick->start();return;
}if(path=="/v1/slow")return;if(path=="/v1/redirect"){socket->write("HTTP/1.1 302 Found\r\nLocation: /v1/ok\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");}else if(path=="/v1/large"){socket->write("HTTP/1.1 200 OK\r\nContent-Length: 65537\r\nConnection: close\r\n\r\n"+QByteArray(65537,'x'));}else if(path=="/v1/quota"){socket->write("HTTP/1.1 429 Too Many Requests\r\nRetry-After: 30\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");}else{socket->write("HTTP/1.1 206 Partial Content\r\nETag: \"abc\"\r\nContent-Range: bytes 0-1/2\r\nContent-Length: 2\r\nConnection: close\r\n\r\nok");}socket->disconnectFromHost();});socket->startServerEncryption();}};
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{VerifiedHttpTransport production;for(const auto& p:QStringList{"https://example.test/v1/x","//example.test/x","/v1/../x","/v1/x?token=secret","/v1/%2fhidden","/v1/x#fragment","/v1/x\n"})rejects([&]{production.request("GET",p,{}, {},20,100);});rejects([&]{production.request("GET","/v1/x",{},{{"X-Test\n","value"}},20,100);});rejects([&]{production.request("GET","/v1/x",{},{{"Authorization","one"},{"authorization","two"}},20,100);});rejects([&]{production.request("DELETE","/v1/x",{},{},20,100);});rejects([&]{production.request("GET","/v1/x",{},{{"Authorization","Bearer x\r\nInjected: value"}},20,100);});rejects([&]{production.request("GET","/v1/x",{},{{"Host","example.test"}},20,100);});rejects([&]{production.request("GET","/v1/x",{},{},20,30001);});rejects([&]{production.request("GET","/v1/x",{},{},67108865,100);});rejects([&]{VerifiedHttpTransport t(VerifiedHttpTransport::ForTests{},QUrl("https://example.test"),QSslCertificate());});if(argc!=3){std::cout<<"HTTP preflight tests passed; TLS fixtures not supplied\n";return 0;}QFile certFile(argv[1]),keyFile(argv[2]);check(certFile.open(QIODevice::ReadOnly)&&keyFile.open(QIODevice::ReadOnly));QSslCertificate cert(certFile.readAll());QSslKey key(keyFile.readAll(),QSsl::Rsa);check(!cert.isNull()&&!key.isNull());Server server(cert,key);check(server.listen(QHostAddress::LocalHost,0));QUrl origin(QString("https://127.0.0.1:%1").arg(server.serverPort()));VerifiedHttpTransport transport(VerifiedHttpTransport::ForTests{},origin,cert);auto response=transport.request("GET","/v1/ok",{},{},2,1000);check(response.status==206&&response.body=="ok"&&response.headers["etag"]=="\"abc\""&&response.headers["content-range"]=="bytes 0-1/2");int before=server.requests;rejects([&]{transport.request("GET","/v1/redirect",{},{},10,1000);});check(server.requests==before+1);rejects([&]{transport.request("GET","/v1/large",{},{},8,1000);});rejects([&]{transport.request("GET","/v1/slow",{},{},10,40);});response=transport.request("GET","/v1/quota",{},{},0,1000);check(response.status==429&&response.headers["retry-after"]=="30");QElapsedTimer elapsed;elapsed.start();response=transport.request("GET","/v1/throttle",{},{},2300000,30000);check(response.status==200&&response.body==QByteArray(2300000,'p')&&elapsed.elapsed()>70000&&elapsed.elapsed()<120000);std::cout<<"HTTP_THROTTLE_PASS bytes=2300000 rate=30000 elapsed_ms="<<elapsed.elapsed()<<" inactivity_ms=30000\n";elapsed.restart();rejects([&]{transport.request("GET","/v1/stall-body",{},{},100,250);});check(elapsed.elapsed()>=200&&elapsed.elapsed()<2000);std::cout<<"HTTP_STALL_PASS elapsed_ms="<<elapsed.elapsed()<<'\n';origin.setHost("localhost");VerifiedHttpTransport wrongHost(VerifiedHttpTransport::ForTests{},origin,cert);rejects([&]{wrongHost.request("GET","/v1/ok",{},{},20,1000);});std::cout<<"HTTP local TLS tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
